/**
 * Replace the library's entire sharing state in one call — the body is the
 * full list of grants (all-initiative-members / per-user / per-role). Every
 * non-owner grant is rebuilt from it; the owner is always preserved.
 *
 * Anyone the new sharing no longer lets open the library is taken off
 * whatever in it names them.
 * @summary Set Library Grants
 */
export const setLibraryGrants = (
  communityId: number,
  libraryId: number,
  resourceGrantSchema: BodyType<ResourceGrantSchema[]>,
  options?: SecondParameter<typeof apiMutator>,
  signal?: AbortSignal
) => {
  return apiMutator<LibraryRead>(
    {
      url: `/api/v1/c/${communityId}/libraries/${libraryId}/grants`,
      method: "PUT",
      headers: { "Content-Type": "application/json" },
      data: resourceGrantSchema,
      signal,
    },
    options
  );
};

